import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: NextRequest) {
  try {
    const userData = await req.json();

    if (!userData || !userData.id) {
      return NextResponse.json({ error: 'Invalid user data' }, { status: 400 });
    }

    let user = await prisma.user.findUnique({
      where: { telegramId: userData.id },
    });

    if (!user) {
      user = await prisma.user.create({
        data: {
          telegramId: userData.id,
          username: userData.username || '',
          firstName: userData.first_name || '',
          lastName: userData.last_name || '',
        },
      });
    }

    return NextResponse.json(user);
  } catch (error) {
    console.error('Error processing user data:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET() {
  try {
    const leaderboardUsers = await prisma.user.findMany({
      orderBy: { points: 'desc' },
      take: 50, // Top 50 users
    });

    return NextResponse.json(leaderboardUsers);
  } catch (error) {
    console.error('Error fetching leaderboard:', error);
    return NextResponse.json(
      { error: 'Failed to fetch leaderboard' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: NextRequest) {
  const { telegramId, referredBy } = await req.json();

  // Update user with referredBy field
  await prisma.user.update({
    where: { telegramId },
    data: { referredBy },
  });

  // Increment points for the referring user
  await prisma.user.update({
    where: { telegramId: referredBy },
    data: { points: { increment: 10 } },
  });

  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: NextRequest) {
  try {
    const { telegramId, taskId } = await req.json();

    // Find user
    const user = await prisma.user.findUnique({
      where: { telegramId },
    });

    // If the user doesn't exist, return an error
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // Update user points
    await prisma.user.update({
      where: { telegramId },
      data: { points: { increment: 10 } },
    });

    // Update task status
    const taskStatus = await prisma.taskStatus.update({
      where: {
        // This should match the compound index you defined
        taskId_userId: {
          taskId: taskId,
          userId: user.id,
        },
      },
      data: { completed: true },
    });

    return NextResponse.json({ user, taskStatus });
  } catch (error) {
    console.error('Error updating task status:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

